def _build_quota_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        eligible = [job for job in jobs if job["id"] not in blocked]
        for mask in range(1 << len(eligible)):
            if mask.bit_count() != k:
                continue
            selected = [eligible[i] for i in range(len(eligible)) if mask & (1 << i)]
            ids = [job["id"] for job in selected]
            if not mandatory.issubset(ids):
                continue

            counts = {}
            for job in selected:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            events = []
            for job in selected:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            active = 0
            valid = True
            for _, change in sorted(events, key=lambda event: (event[0], event[1])):
                active += change
                if active > capacity:
                    valid = False
                    break
            if not valid:
                continue

            total = sum(job["value"] for job in selected)
            ordered_ids = sorted(ids)
            better_tie = (best_ids is None or
                          (ordered_ids > best_ids if tie == "largest" else ordered_ids < best_ids))
            if best_value is None or total > best_value or (total == best_value and better_tie):
                best_value, best_ids = total, ordered_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, mode):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    def amount(event, mode):
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), mode)
        tax = rounded(raw * event.get("tax_bp", 0), mode)
        total = net + tax
        return -total if event.get("kind") == "refund" else total

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for pos, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = (sequence, event.get("revision", 0), pos)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount(event, data["rounding"])
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        domains = []
        for name in names:
            rows = [row for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            domains.append([None] + rows)

        best_vector = None
        best = None
        roots = data["roots"]
        for choices in product(*domains):
            assignment = {name: row for name, row in zip(names, choices) if row is not None}
            reachable = set()
            visited = set()
            active = set()
            edges = {}

            def visit(name, low, high):
                row = assignment.get(name)
                if row is None or not low <= row["version"] <= high:
                    return False
                if name in active:
                    return False
                if name in visited:
                    return True
                active.add(name)
                reachable.add(name)
                deps = [dep for dep in row.get("deps", [])
                        if not dep.get("feature") or dep["feature"] in features]
                edges[name] = [dep["name"] for dep in deps]
                for dep in deps:
                    if not visit(dep["name"], dep["min"], dep["max"]):
                        return False
                active.remove(name)
                visited.add(name)
                return True

            valid = True
            for name, bounds in roots.items():
                if not visit(name, bounds[0], bounds[1]):
                    valid = False
                    break
            if not valid or reachable != set(assignment):
                continue
            vector = tuple(assignment[name]["version"] if name in assignment else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector, best = vector, {
                    name: assignment[name]["version"] for name in names if name in assignment
                }

        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial_mask = bit_for.get(source, 0)
        start_state = (source, data["coupons"], initial_mask)
        start_time = data["start"]
        distances = {start_state: start_time}
        queue = [(start_time, source, data["coupons"], initial_mask)]

        while queue:
            time, node, remaining, mask = heapq.heappop(queue)
            state = (node, remaining, mask)
            if distances.get(state) != time:
                continue
            if node == data["target"] and remaining == 0 and mask == full:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                transitions = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    transitions.append((duration, remaining - 1))
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                for duration, next_remaining in transitions:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_state = (next_node, next_remaining, next_mask)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_remaining, next_mask))
        return {"arrival": None}
    return solve


